```js
// Perform a swept AABB (rectangle + radius) vs axis-aligned movement.
// P0 -> P1 is the ball center path, r the radius.
// Returns null if no hit, or { t, nx, ny } where (nx,ny) is the unit normal
// of the face hit and t in [0,1] the time of first contact.
function sweptHit(brick, p0x, p0y, p1x, p1y, r) {
  const dx = p1x - p0x;
  const dy = p1y - p0y;
  let tmin = 0, tmax = 1;
  let nx = 0, ny = 0;

  // X slab [brick.x - r, brick.x + brick.w + r]
  {
    let t0, t1, side;
    if (dx !== 0) {
      t0 = (brick.x - r - p0x) / dx;
      t1 = (brick.x + brick.w + r - p0x) / dx;
      side = -1; // entering from left -> normal -1
      if (t0 > t1) { [t0, t1] = [t1, t0]; side = 1; }
      if (t0 > tmin) { tmin = t0; nx = side; ny = 0; }
      if (t1 < tmax) tmax = t1;
    } else if (p0x < brick.x - r || p0x > brick.x + brick.w + r) {
      return null; // never overlapping in x
    }
  }
  // Y slab
  {
    let t0, t1, side;
    if (dy !== 0) {
      t0 = (brick.y - r - p0y) / dy;
      t1 = (brick.y + brick.h + r - p0y) / dy;
      side = -1; // entering from top -> normal -1
      if (t0 > t1) { [t0, t1] = [t1, t0]; side = 1; }
      if (t0 > tmin) { tmin = t0; nx = 0; ny = side; }
      if (t1 < tmax) tmax = t1;
    } else if (p0y < brick.y - r || p0y > brick.y + brick.h + r) {
      return null;
    }
  }
  if (tmin <= tmax && tmin < 1) {
    return { t: Math.max(0, tmin), nx, ny };
  }
  return null;
}
```

