  const brick = brickAt(200, 200); // y in [200,220]
  const ball = { x: 220, y: 0, r: 7, vx: 0, vy: 400 };
  // ...but the swept segment from prev position (y=40) to current (y=440)
  // crosses the brick, so the bounce must still fire.
