// Runs brick collision for a whole state: destroys every touched brick, applies
// score & combo, and lets `resolveBrickHit` flip the ball off the first surface
// it meets. Push-out guarantees the bounce is applied exactly once per pass even
// when the ball overlaps two neighbouring bricks at once.
export function applyBrickHits(state) {
  const { ball, bricks } = state;
  let hit = false;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (resolveBrickHit(ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      hit = true;
    }
  }
  return hit;
}

