test('neighbours: two bricks overlapped in one pass bounce exactly once', () => {
  // Two side-by-side bricks with the 8px seam; ball clips both at once.
  const a = brickAt(100, 100); // x in [100,140]
  const b = brickAt(148, 100); // x in [148,188]
  const ball = { x: 144, y: 104, r: 7, vx: 0, vy: 250 }; // clips the top of both seams
  resolveBrickHit(ball, a);
  resolveBrickHit(ball, b);
  assert.equal(ball.vy, -250, 'y-velocity flipped exactly once, not cancelled to 0');
  assert.equal(collides(ball, a), false, 'not stuck inside the first brick');
  assert.equal(collides(ball, b), false, 'not stuck inside the second brick');
});

