test('neighbours: two bricks overlapped in one pass bounce exactly once', () => {
  // Two bricks stacked across the 8px horizontal seam; a 14px ball overlaps
  // both at once (bottom face of `a` AND top face of `b`) while moving down.
  const state = { bricks: [brickAt(100, 100), brickAt(100, 128)], combo: 0, score: 0 };
  state.ball = { x: 120, y: 124, r: 7, vx: 0, vy: 250 };
  applyBrickHits(state);
  // vy must flip exactly ONCE (-250), not twice (+250 again => plow-through).
  assert.equal(state.ball.vy, -250, 'y-velocity flipped exactly once, not cancelled');
  assert.equal(state.ball.vx, 0, 'vx untouched by a top/bottom pass');
  assert.ok(state.ball.y + state.ball.r <= 100, 'ball pushed clear of both bricks');
  assert.ok(state.bricks.every((b) => !b.alive), 'both overlapping bricks destroyed');
});

