function minPenetration(ball, brick) {
  const overlapX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  return Math.min(overlapX, overlapY);
}

// Runs brick collision for a whole state: destroys every touched brick, applies
// score & combo, and lets the ball bounce off the brick it entered most cleanly.
// The velocity flip is applied EXACTLY ONCE per pass: the 8 px grid seam lets a
// 14 px ball overlap two neighbouring bricks at once, and `vy = -vy` (or vx)
// applied twice cancels out - the ball would otherwise plow straight through.
// After the single bounce the ball is pushed clear of every touched brick.
export function applyBrickHits(state) {
  const { ball, bricks } = state;
  const prevX = ball.prevX ?? ball.x;
  const prevY = ball.prevY ?? ball.y;

  // Pass 1: find every brick the ball touches (overlap, or a swept tunnel hit),
  // destroying it and scoring without yet mutating the ball.
  const touched = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick) || sweptBrickHit(brick, prevX, prevY, ball.x, ball.y, ball.r)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      touched.push(brick);
    }
  }
  if (touched.length === 0) return false;

  // Pass 2: a single bounce. Prefer the cleanest (least-penetrated) overlap; if
  // the ball only tunnelled, bounce off the first swept contact.
  const overlaps = touched.filter((b) => collides(ball, b));
  if (overlaps.length > 0) {
    let chosen = overlaps[0];
    for (const b of overlaps) {
      if (minPenetration(ball, b) < minPenetration(ball, chosen)) chosen = b;
    }
    resolveBrickHit(ball, chosen);
  } else {
    for (const b of touched) {
      if (resolveBrickHit(ball, b, prevX, prevY)) break;
    }
  }

  // Pass 3: clear the ball out of any brick it still overlaps (no velocity
  // change) so it does not stick or look inside a brick on the next frame.
  for (const b of touched) pushOutOf(ball, b);

  return true;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball started this step so brick collision can sweep the
  // travelled segment (high-speed steps would otherwise tunnel through a brick,
  // see #1).
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

